import{_ as t,o,c as a,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const b=JSON.parse('{"title":"2023年 · 缔造者芒格谢幕","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2023年.md","filePath":"05_quotes/by-year/2023年.md"}'),r={name:"05_quotes/by-year/2023年.md"};function u(q,e,s,c,h,i){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_2023年-·-缔造者芒格谢幕" tabindex="-1">2023年 · 缔造者芒格谢幕 <a class="header-anchor" href="#_2023年-·-缔造者芒格谢幕" aria-label="Permalink to &quot;2023年 · 缔造者芒格谢幕&quot;">​</a></h1><blockquote><p>查理是今日伯克希尔的&quot;缔造者&quot;，而我则担任&quot;总承包商&quot;，负责日复一日地实现他的愿景。——巴菲特（93岁）</p></blockquote><p>本页收录2023年致股东信中的经典语录。本年是查理·芒格的谢幕之年，巴菲特深情追忆这位64年的挚友，称其为伯克希尔的真正缔造者。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>查理是今日伯克希尔的&quot;缔造者&quot;，而我则担任&quot;总承包商&quot;，负责日复一日地实现他的愿景。</p></blockquote><blockquote><p>查理从不寻求将创造者的角色归功于自己，而是让我接受掌声和赞誉。从某种意义上说，他与我的关系既是兄长，又是慈父。</p></blockquote><blockquote><p>短期内，市场是一台投票机；长期来看，它变成了一台称重机。</p></blockquote><blockquote><p>美国一直是投资者的乐土。他们需要做的只是安静地坐着，不听任何人的话。</p></blockquote><blockquote><p>华尔街——用其比喻意义来说——希望它的客户赚钱，但真正让从业者兴奋的是疯狂的交易活动。</p></blockquote><blockquote><p>伯克希尔有一条投资规则从未改变，将来也不会改变：永远不要冒永久性资本损失的风险。</p></blockquote><blockquote><p>当你发现一家真正出色的企业时，坚持持有它。耐心是有回报的，一家有出色的企业可以抵消许多不可避免的平庸决策。</p></blockquote><blockquote><p>永远不要指望在与骗子打交道时能阻止他欺骗你。</p></blockquote><hr><h2 id="芒格的贡献" tabindex="-1">芒格的贡献 <a class="header-anchor" href="#芒格的贡献" aria-label="Permalink to &quot;芒格的贡献&quot;">​</a></h2><blockquote><p>&quot;沃伦，别再想着收购像伯克希尔这样的公司了。但既然你已经控制了伯克希尔，就用合理的价格收购优秀企业并不断添加到公司中，而不要再用离谱的价格去买普通的企业。&quot;</p></blockquote><blockquote><p>放弃你从英雄本杰明·格雷厄姆那里学到的一切。它有效，但只在小型规模上实践时才有效。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2023年11月28日，查理·芒格去世，距100岁生日仅差33天。巴菲特在信中深情追忆这位64年的挚友，称芒格1965年的建议——放弃&quot;捡便宜&quot;策略、以合理价格收购优秀企业——改变了伯克希尔的命运。本年经营收益达374亿美元，创历史新高。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2023年-翻译-·-01-letters-2023年-核心总结-·-01-letters-2023年-思维导图" tabindex="-1"><a href="/01_letters/2023年/翻译.html">01_letters/2023年/翻译</a> · <a href="/01_letters/2023年/核心总结.html">01_letters/2023年/核心总结</a> · <a href="/01_letters/2023年/思维导图.html">01_letters/2023年/思维导图</a> <a class="header-anchor" href="#_01-letters-2023年-翻译-·-01-letters-2023年-核心总结-·-01-letters-2023年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2023年/翻译]] · [[→ 核心总结|01_letters/2023年/核心总结]] · [[→ 思维导图|01_letters/2023年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2023年/翻译.html">/01_letters/2023年/翻译</a></li></ul>',25)])])}const n=t(r,[["render",u]]);export{b as __pageData,n as default};
